class Session {
  #socket; #closed = false;
  constructor(socket) { this.#socket = socket; }
  [Symbol.dispose]() {                        // idempotent cascade, owned only
    if (this.#closed) return;
    this.#closed = true; this.#socket.close();
  }
}
function handle() {
  using session = new Session(connect());
  return session.roundTrip();                 // disposed on return or throw
}
